  readonly Dictionary<string,ImageSource> inspectorImages=new Dictionary<string,ImageSource>();
  ImageSource InspectorImage(string path){ImageSource cached;if(inspectorImages.TryGetValue(path,out cached))return cached;try{var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=180;image.UriSource=new Uri(Path.GetFullPath(path));image.EndInit();image.Freeze();inspectorImages[path]=image;return image;}catch{return null;}}
  ImageSource StickerThumbnail(OverlayClip clip){string key="sticker:"+clip.ImageData.GetHashCode();ImageSource cached;if(inspectorImages.TryGetValue(key,out cached))return cached;try{using(var bytes=new MemoryStream(Convert.FromBase64String(clip.ImageData))){var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=140;image.StreamSource=bytes;image.EndInit();image.Freeze();inspectorImages[key]=image;return image;}}catch{return null;}}
  Button InspectorAction(string icon,string text,Action action,bool quiet=false){var button=UI.Button("",action);button.Content=UI.IconLabel(icon,text,13);button.HorizontalContentAlignment=HorizontalAlignment.Center;button.Margin=new Thickness(0,4,0,8);if(quiet)button.Style=(Style)Window.FindResource("PlainButton");return button;}
  Button MediaTile(string title,Brush background,ImageSource image,bool selected,Action action,int height=72){var grid=new Grid {Height=height,ClipToBounds=true,Background=background};if(image!=null)grid.Children.Add(new Image {Source=image,Stretch=Stretch.UniformToFill});if(selected){var badge=new Border {Width=18,Height=18,CornerRadius=new CornerRadius(9),Background=Brushes.White,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Top,Margin=new Thickness(5),Child=new TextBlock {Text="✓",FontSize=11,Foreground=UI.Brush("#292B2D"),HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center}};grid.Children.Add(badge);}var clip=new Border {CornerRadius=new CornerRadius(11),Child=grid};clip.SizeChanged+=(s,e)=>clip.Clip=new RectangleGeometry(new Rect(0,0,clip.ActualWidth,clip.ActualHeight),11,11);var stack=new StackPanel();stack.Children.Add(clip);var label=UI.Text(title,10,"#63696D");label.TextWrapping=TextWrapping.NoWrap;label.TextTrimming=TextTrimming.CharacterEllipsis;label.HorizontalAlignment=HorizontalAlignment.Center;label.Margin=new Thickness(0,6,0,2);stack.Children.Add(label);var button=UI.Button("",action);button.Content=stack;button.HorizontalContentAlignment=HorizontalAlignment.Stretch;button.ToolTip=title;button.Padding=new Thickness(3);button.Margin=new Thickness(2,3,2,5);button.BorderThickness=new Thickness(selected?2:.6);UI.Role(button,Control.BorderBrushProperty,selected?"Ink":"Line");button.Background=Brushes.Transparent;return button;}
  void BuildBackgroundInspector(){var a=Doc.Style;Section("背景素材");Buttons(new[]{"壁纸","图案","自定义"},backgroundPage,value=>{backgroundPage=value;Find<ScrollViewer>("InspectorScroll").ScrollToTop();BuildInspector();});
   if(backgroundPage=="壁纸"){var files=new List<string>();string bundled=Path.GetFullPath(Path.Combine(Media.Root,"../Resources/Onboarding/SoftLight.png"));if(File.Exists(bundled))files.Add(bundled);try{string current=Microsoft.Win32.Registry.GetValue(@"HKEY_CURRENT_USER\Control Panel\Desktop","WallPaper","") as string;if(!string.IsNullOrWhiteSpace(current)&&File.Exists(current))files.Add(current);string folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"Web","Wallpaper");if(Directory.Exists(folder))files.AddRange(Directory.EnumerateFiles(folder,"*.jpg",SearchOption.AllDirectories).Take(11));}catch{}var grid=new UniformGrid {Columns=3};foreach(string path in files.Distinct(StringComparer.OrdinalIgnoreCase)){string file=path;var image=InspectorImage(file);if(image==null)continue;string label=file==bundled?"柔光":Path.GetFileNameWithoutExtension(file);grid.Children.Add(MediaTile(label,Brushes.Transparent,image,a.Background=="image"&&string.Equals(a.ImagePath,file,StringComparison.OrdinalIgnoreCase),()=>{Checkpoint();a.Background="image";a.ImagePath=file;Changed();BuildInspector();},68));}inspector.Children.Add(grid);Note("本机壁纸与原版柔光背景。选择缩略图即可应用。");}
   else if(backgroundPage=="图案"){string[][] presets={new[]{"网点","#F5F6F7","#F5F6F7","dots"},new[]{"纯白","#FFFFFF","#FFFFFF","solid"},new[]{"石墨","#24272B","#24272B","solid"},new[]{"薄荷","#DEF2E8","#A3CABB","gradient"},new[]{"海湾","#164A65","#8FD7D4","gradient"},new[]{"暮色","#33365F","#C8A6DC","gradient"},new[]{"落日","#F6BFAA","#CC6F86","gradient"},new[]{"沙丘","#E3D7C8","#BDA88E","gradient"},new[]{"冰川","#DDE7EF","#A3BDD8","gradient"}};var grid=new UniformGrid {Columns=3};foreach(var item in presets){var p=item;Brush paint=p[3]=="dots"?UI.WorkspaceDots(false):(Brush)new LinearGradientBrush((Color)ColorConverter.ConvertFromString(p[1]),(Color)ColorConverter.ConvertFromString(p[2]),45);bool selected=a.Background==p[3]&&a.ColorA==p[1]&&a.ColorB==p[2];grid.Children.Add(MediaTile(p[0],paint,null,selected,()=>{Checkpoint();a.Background=p[3];a.ColorA=p[1];a.ColorB=p[2];Changed();BuildInspector();}));}inspector.Children.Add(grid);}
   else {Section("自定义图片");if(a.Background=="image"&&File.Exists(a.ImagePath)){inspector.Children.Add(MediaTile(Path.GetFileName(a.ImagePath),Brushes.Transparent,InspectorImage(a.ImagePath),true,ChooseInspectorBackground,112));}inspector.Children.Add(InspectorAction("plus","选择图片…",ChooseInspectorBackground));Note("支持 PNG、JPG、BMP。预览与导出使用同一张背景图片。");}
   Section("背景颜色");ColorButton("颜色",a.ColorA,value=>{a.ColorA=value;if(a.Background!="gradient")a.Background="solid";});if(a.Background=="gradient")ColorButton("渐变终点",a.ColorB,value=>a.ColorB=value);
  }
  void ChooseInspectorBackground(){var dialog=new Microsoft.Win32.OpenFileDialog {Filter="图片|*.png;*.jpg;*.jpeg;*.bmp"};if(dialog.ShowDialog(Window)!=true)return;Checkpoint();Doc.Style.ImagePath=dialog.FileName;Doc.Style.Background="image";backgroundPage="自定义";Changed();BuildInspector();}
  void PresetGallery(){if(Doc==null)return;var menu=UI.PopupMenu(Window,Find<Button>("Presets"));Find<Button>("Presets").ContextMenu=menu;var grid=new UniformGrid {Columns=2,Width=300};string[] names={"简洁窗口","原始全屏","薄荷演示","深色展示"};for(int i=0;i<names.Length;i++){int choice=i;string color=i==2?"#DEF2E8":i==3?"#24272B":"#F5F6F7";var preview=new DrawingGroup();using(var dc=preview.Open()){dc.DrawRectangle(UI.Brush(color),null,new Rect(0,0,140,78));Rect screen=i==1?new Rect(0,0,140,78):new Rect(16,14,108,54);dc.DrawRoundedRectangle(UI.Brush(i==3?"#414348":"#FFFFFF"),null,screen,i==1?0:5,i==1?0:5);if(thumbs.Count>0)dc.DrawImage(thumbs[0],new Rect(screen.X,screen.Y+(i==1?0:7),screen.Width,screen.Height-(i==1?0:7)));if(i!=1)for(int dot=0;dot<3;dot++)dc.DrawEllipse(UI.Brush(new[]{"#FF6259","#FDBC40","#35C84A"}[dot]),null,new Point(screen.X+5+dot*4,screen.Y+3.5),1.1,1.1);}var image=new DrawingImage(preview);image.Freeze();grid.Children.Add(MediaTile(names[i],Brushes.Transparent,image,false,()=>{Checkpoint();Doc.Style.Padding=choice==1?0:70;Doc.Style.Radius=choice==1?0:16;Doc.Style.Frame=choice==1?"none":"window";Doc.Style.Background=choice==0?"dots":choice==1?"solid":"gradient";Doc.Style.ColorA=choice==2?"#DEF2E8":choice==3?"#24272B":"#F5F6F7";Doc.Style.ColorB=choice==2?"#9EC7B8":choice==3?"#566171":"#F5F6F7";menu.IsOpen=false;Changed();BuildInspector();},78));}menu.Items.Add(new MenuItem {Header=grid,StaysOpenOnClick=true,Padding=new Thickness(3)});menu.IsOpen=true;}
  void InspectorColor(string label,string value,Action<string> change){InspectorHexColor(label,value,change);}
  void OverlayLibrary(bool sticker){var clips=Doc.Overlays.Select((clip,index)=>new {Clip=clip,Index=index}).Where(p=>(p.Clip.Kind=="sticker")==sticker).ToList();if(clips.Count==0){var empty=new Border {CornerRadius=new CornerRadius(14),Padding=new Thickness(16,20,16,20),Margin=new Thickness(0,12,0,0)};UI.Role(empty,Border.BackgroundProperty,"Well");var stack=new StackPanel();var icon=UI.Icon(sticker?"sticker":"soften",28);icon.HorizontalAlignment=HorizontalAlignment.Center;stack.Children.Add(icon);var text=UI.Text(sticker?"添加图片，让演示更生动":"柔化敏感信息，突出关键区域",12,"#63696D");text.TextAlignment=TextAlignment.Center;text.Margin=new Thickness(0,10,0,0);stack.Children.Add(text);empty.Child=stack;inspector.Children.Add(empty);return;}
   Section(sticker?"贴图素材":"柔化区域");foreach(var item in clips){int index=item.Index;var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition {Width=new GridLength(48)});grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition {Width=GridLength.Auto});var thumbnail=new Border {Width=40,Height=40,CornerRadius=new CornerRadius(8),Margin=new Thickness(0,0,8,0)};UI.Role(thumbnail,Border.BackgroundProperty,"Well");thumbnail.Child=sticker?(UIElement)new Image {Source=StickerThumbnail(item.Clip),Stretch=Stretch.Uniform,Margin=new Thickness(3)}:UI.Icon("soften",19);grid.Children.Add(thumbnail);var text=new StackPanel {VerticalAlignment=VerticalAlignment.Center};var name=UI.Text(item.Clip.Name,12);name.TextWrapping=TextWrapping.NoWrap;name.TextTrimming=TextTrimming.CharacterEllipsis;text.Children.Add(name);text.Children.Add(UI.Text(UI.Time(item.Clip.Start)+" – "+UI.Time(item.Clip.End),10,"#858A8E"));Grid.SetColumn(text,1);grid.Children.Add(text);var arrow=UI.Icon("chevron",10);Grid.SetColumn(arrow,2);grid.Children.Add(arrow);var b=UI.Button("",()=>SelectEffect(index));b.Content=grid;b.HorizontalContentAlignment=HorizontalAlignment.Stretch;b.Margin=new Thickness(0,3,0,3);b.Padding=new Thickness(9,8,9,8);inspector.Children.Add(b);}
  }
  void OverlayHeading(OverlayClip clip){var row=new DockPanel {Margin=new Thickness(0,9,0,12)};var back=InspectorAction("previous","素材列表",()=>{selectedOverlay=-1;BuildInspector();DrawEffectGuides();},true);back.FontSize=10;back.Padding=new Thickness(2);back.MinHeight=24;DockPanel.SetDock(back,Dock.Right);row.Children.Add(back);var title=UI.Text(clip.Name,12);title.FontWeight=FontWeights.SemiBold;title.TextTrimming=TextTrimming.CharacterEllipsis;title.TextWrapping=TextWrapping.NoWrap;title.VerticalAlignment=VerticalAlignment.Center;row.Children.Add(title);inspector.Children.Add(row);if(clip.Kind=="sticker"){var image=new Image {Source=StickerThumbnail(clip),Height=76,Stretch=Stretch.Uniform,Margin=new Thickness(10)};var card=new Border {CornerRadius=new CornerRadius(12),Child=image};UI.Role(card,Border.BackgroundProperty,"Well");inspector.Children.Add(card);}}
  void CursorStylePreview(){var doc=new EditDocument {Width=800,Height=280,Duration=1,IndependentCursor=true};doc.Cuts.Add(new Cut {Start=0,End=1});doc.Pointer.Add(new DogSC.Windows.PointerSample {Time=0,X=.5,Y=.5,Visible=true,Click=true,CursorKind="arrow"});doc.Cursor=EditDocument.Serializer().Deserialize<CursorSettings>(EditDocument.Serializer().Serialize(Doc.Cursor));doc.Cursor.Size*=5;doc.Cursor.TimeOffset=0;doc.Style.Padding=0;doc.Style.Frame="none";doc.Style.Scale=1;var image=new Image {Height=86,Stretch=Stretch.Uniform};using(var bitmap=new System.Drawing.Bitmap(800,280))using(var g=System.Drawing.Graphics.FromImage(bitmap))using(var motion=new MotionEvaluator(doc))using(var bytes=new MemoryStream()){g.Clear(System.Drawing.Color.Transparent);g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;var pose=new Pose();EffectRenderer.Cursor(g,doc,motion,.12,SceneLayout.Make(doc,800,280,pose),pose,800,280);bitmap.Save(bytes,System.Drawing.Imaging.ImageFormat.Png);image.Source=UI.Image(bytes.ToArray());}var card=new Border {CornerRadius=new CornerRadius(13),Child=image,Margin=new Thickness(0,4,0,12)};UI.Role(card,Border.BackgroundProperty,"Well");inspector.Children.Add(card);}
